 async function importPayrollFile(file){setPayrollBusy(true);setErr("");setPayrollMessage("");try{const bytes=await file.arrayBuffer();const digest=await crypto.subtle.digest("SHA-256",bytes);const hash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,"0")).join("");const duplicate=payrollBatches.find(x=>x.file_sha256===hash);if(duplicate)throw Error("This exact file was already imported on "+new Date(duplicate.imported_at).toLocaleString()+". Duplicate upload blocked.");const wb=new ExcelJS.Workbook();await wb.xlsx.load(bytes);const sheet=wb.worksheets[0];if(!sheet)throw Error("The workbook has no worksheets.");const headers=[];sheet.getRow(1).eachCell({includeEmpty:true},(c,i)=>{headers[i-1]=cell(c.value)||("Column "+i);});if(!headers.some(Boolean))throw Error("Could not find column headings in the first row.");const nameIndex=headers.findIndex(h=>/^(employee\s*name|staff\s*name|name)$/i.test(String(h).trim()));const idIndex=headers.findIndex(h=>/^(staff\s*id|employee\s*id|id)$/i.test(String(h).trim()));const rawRows=[];sheet.eachRow((row,n)=>{if(n===1)return;const obj={};headers.forEach((h,i)=>{if(h)obj[h]=cell(row.getCell(i+1).value);});if(Object.values(obj).some(v=>String(v||"").trim()))rawRows.push({source_row_number:n,staff_id:idIndex>=0?String(cell(row.getCell(idIndex+1).value)||"").trim()||null:null,employee_name_source:nameIndex>=0?String(cell(row.getCell(nameIndex+1).value)||"").trim()||null:null,raw_data:{sheet:sheet.name,values:obj}});});if(!rawRows.length)throw Error("No payroll data rows found below the header.");const batch=await dbRequest("import_batches?select=id",{method:"POST",headers:{"Prefer":"return=representation"},body:JSON.stringify({source_type:"pagarbook_payroll",file_name:file.name,file_sha256:hash,row_count:rawRows.length,status:"uploaded",metadata:{worksheet:sheet.name,columns:headers.filter(Boolean),original_file_size:file.size}})});const batchId=batch?.[0]?.id;if(!batchId)throw Error("The import batch was not created.");for(let i=0;i<rawRows.length;i+=100){const part=rawRows.slice(i,i+100).map(r=>({...r,batch_id:batchId}));await dbRequest("payroll_source_rows",{method:"POST",headers:{"Prefer":"return=minimal"},body:JSON.stringify(part)});}setSelectedBatch(batchId);await loadPayrollHistory();setPayrollMessage("Successfully imported "+rawRows.length+" original payroll rows from "+file.name+". Original cell values are retained; no salary values were modified.");}catch(e){setErr("Payroll import failed: "+(e.message||"Unknown error"));}finally{setPayrollBusy(false);}}
