 const salaryColumns=["S.N.","Staff Name","Site","Designation","Date of Joining","Total CTC","Basic","DA","HRA","Salary Payable","Payable Days","Absent Days","Expense Claim","Allowance","System Overtime","Total Salary Payable","Loan Instalment","PF","PT","Food Expense","ESI","System Fine","Advance","Total Deduction","Net Payable Amount"]; const salaryGet=(r,...keys)=>{const values=r.raw_data?.values||{};for(const k of keys){const direct=values[k];if(direct!==undefined&&direct!==null&&String(direct).trim()!=="")return direct;const wanted=norm(k);const actual=Object.keys(values).find(h=>norm(h)===wanted);if(actual!==undefined&&values[actual]!==undefined&&values[actual]!==null&&String(values[actual]).trim()!=="")return values[actual];}return "";}; const salaryNum=v=>{const raw=String(v??"").trim();if(!raw)return 0;const negative=/^\(.*\)$/.test(raw);const cleaned=raw.replace(/[₹,\s]/g,"").replace(/[()]/g,"").replace(/[^0-9.\-]/g,"");const n=Number(cleaned);return Number.isFinite(n)?(negative?-Math.abs(n):n):0;};
 const salarySiteOf=r=>String(salaryGet(r,"Site","Project Site","Work Site")||"Unassigned").trim()||"Unassigned";
