   win.document.write("<!doctype html><html><head><title>Crescent Contractors Salary Bill</title><style>@page{size:A3 landscape;margin:10mm 10mm 15mm}*{box-sizing:border-box}body{font:10px Arial;color:#17232b;margin:0}h1{text-align:center;font-size:23px;margin:0 0 2mm;font-weight:700}h2{text-align:center;font-size:17px;margin:0 0 5mm;font-weight:600}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1.25px solid #344b59;padding:2px 3px;vertical-align:middle}th{background:#eaf0f3;font-size:9px;white-space:normal;text-align:center;line-height:1.1}td{font-size:9.5px;white-space:nowrap;overflow:hidden;text-overflow:clip;height:10mm;line-height:1.05}th:nth-child(2),td:nth-child(2){width:11%;text-align:left}th:nth-child(4),td:nth-child(4){width:8.5%;text-align:left}.subtotal{font-weight:bold;background:#e8eef1}.grand{font-weight:bold;background:#1b3542;color:white}tr{break-inside:avoid;page-break-inside:avoid;height:10mm}thead{display:table-header-group}.subtotal td,.grand td{height:10mm}.print-footer{position:static;display:block;margin-top:5mm;padding-top:2mm;text-align:center;font:8px Arial;color:#52636d;break-inside:avoid;page-break-inside:avoid}</style></head><body><h1>Crescent Contractors</h1><h2>Salary Bill – "+esc(salaryMonthLabel)+"</h2><table><thead><tr>"+headers+"</tr></thead><tbody>"+groupsHtml+rowHtml(grand,"grand")+"</tbody></table><div class=\"print-footer\">Generated through Crescent Payroll Software</div><script>window.onload=()=>window.print()<\/script></body></html>");
