 {(()=>{const record=salaryMappedRows.find(r=>r.source.id===payslipEmployeeId);if(!record)return null;const v=record.values;const monthLabel=salaryMonth?new Date(salaryMonth+"-01T00:00:00").toLocaleDateString("en-IN",{month:"long",year:"numeric"}):"Salary Period";const earnings=[["Basic",v["Basic"]],["DA",v["DA"]],["HRA",v["HRA"]],["Expense Claim",v["Expense Claim"]],["Allowance",v["Allowance"]],["System Overtime",v["System Overtime"]]];const deductions=[["Loan Instalment",v["Loan Instalment"]],["PF",v["PF"]],["PT",v["PT"]],["Food Expense",v["Food Expense"]],["ESI",v["ESI"]],["System Fine",v["System Fine"]],["Advance",v["Advance"]]];const printSlip=()=>{const esc=x=>String(x??"—").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));const money=x=>salaryDisplay(x===""?"":x)||"—";const lines=(arr)=>arr.filter(([,x])=>x!==""&&x!==null&&x!==undefined).map(([k,x])=>"<tr><td>"+esc(k)+"</td><td class='num'>"+esc(money(x))+"</td></tr>").join("");const w=window.open("","_blank","width=900,height=900");if(!w){setErr("Allow pop-ups to print the payslip.");return;}w.document.write("<!doctype html><html><head><title>Payslip - "+esc(v["Staff Name"])+" - "+esc(monthLabel)+"</title><style>@page{size:A4;margin:16mm}body{font:13px Arial;color:#17232b}h1,h2{text-align:center;margin:0}h1{font-size:22px}h2{font-size:16px;margin:5px 0 22px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:9px 24px;border:1px solid #667985;padding:14px;margin-bottom:18px}.wrap{display:grid;grid-template-columns:1fr 1fr;gap:16px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #526775;padding:9px;text-align:left}th{background:#eaf0f3}.num{text-align:right}.total{font-weight:bold;background:#edf2f5}.net{margin-top:18px;padding:14px;border:2px solid #263f4d;font-size:18px;font-weight:bold;text-align:right}.footer{text-align:center;margin-top:35px;color:#52636d;font-size:10px}</style></head><body><h1>Crescent Contractors</h1><h2>Salary Slip – "+esc(monthLabel)+"</h2><div class='meta'><div><b>Employee:</b> "+esc(v["Staff Name"])+"</div><div><b>Staff ID:</b> "+esc(record.source.staff_id||"—")+"</div><div><b>Site:</b> "+esc(v.Site)+"</div><div><b>Designation:</b> "+esc(v.Designation)+"</div><div><b>Date of Joining:</b> "+esc(v["Date of Joining"])+"</div><div><b>Payable Days:</b> "+esc(v["Payable Days"])+"</div><div><b>Absent Days:</b> "+esc(v["Absent Days"])+"</div><div><b>Total CTC:</b> ₹"+esc(money(v["Total CTC"]))+"</div></div><div class='wrap'><table><thead><tr><th colspan='2'>Earnings</th></tr></thead><tbody>"+lines(earnings)+"<tr class='total'><td>Total Salary Payable</td><td class='num'>"+esc(money(v["Total Salary Payable"]))+"</td></tr></tbody></table><table><thead><tr><th colspan='2'>Deductions</th></tr></thead><tbody>"+lines(deductions)+"<tr class='total'><td>Total Deduction</td><td class='num'>"+esc(money(v["Total Deduction"]))+"</td></tr></tbody></table></div><div class='net'>Net Payable Amount: ₹"+esc(money(v["Net Payable Amount"]))+"</div><div class='footer'>Generated through Crescent Payroll Software</div><script>window.onload=()=>window.print()<\\/script></body></html>");w.document.close();};
 return <div style={{marginTop:18,background:"#0b1c26",border:"1px solid #36515f",borderRadius:12,padding:18}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap"}}><h3 style={{margin:0}}>Payslip Preview</h3><button onClick={printSlip} style={{background:"#d5a84e",color:"#101820",border:0,borderRadius:8,padding:"10px 16px",fontWeight:700}}>Print / Save as PDF</button></div><h2 style={{textAlign:"center",marginBottom:4}}>Crescent Contractors</h2><h3 style={{textAlign:"center",marginTop:0}}>Salary Slip – {monthLabel}</h3><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:10,margin:"18px 0"}}>{[["Employee",v["Staff Name"]],["Staff ID",record.source.staff_id||"—"],["Site",v.Site],["Designation",v.Designation],["Date of Joining",v["Date of Joining"]],["Payable Days",v["Payable Days"]],["Absent Days",v["Absent Days"]],["Total CTC","₹"+salaryDisplay(v["Total CTC"]) ]].map(([k,x])=><div key={k}><small style={{color:"#9fb1bf"}}>{k}</small><div style={{fontWeight:700}}>{x||"—"}</div></div>)}</div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:14}}>{[["Earnings",earnings],["Deductions",deductions]].map(([title,items])=><div key={title}><h4>{title}</h4><table style={{width:"100%",borderCollapse:"collapse"}}><tbody>{items.filter(([,x])=>x!==""&&x!==null&&x!==undefined).map(([k,x])=><tr key={k}><td style={{padding:8,borderBottom:"1px solid #36515f"}}>{k}</td><td style={{padding:8,borderBottom:"1px solid #36515f",textAlign:"right"}}>{salaryDisplay(x)}</td></tr>)}</tbody></table></div>)}</div><div style={{display:"flex",justifyContent:"space-between",gap:12,flexWrap:"wrap",borderTop:"1px solid #547080",marginTop:16,paddingTop:14,fontWeight:700}}><span>Total Salary Payable: ₹{salaryDisplay(v["Total Salary Payable"])}</span><span>Total Deduction: ₹{salaryDisplay(v["Total Deduction"])}</span><span style={{color:"#e6b85c"}}>Net Payable: ₹{salaryDisplay(v["Net Payable Amount"])}</span></div><p style={{textAlign:"center",color:"#9fb1bf",fontSize:11,marginTop:24}}>Generated through Crescent Payroll Software</p></div>;
 })()}
